/**
 * @name ReDoS data flow analysis
 * @description Check if regex patterns from re.compile receive untrusted input
 * @kind problem
 * @problem.severity warning
 * @id py/redos-dataflow
 * @tags security
 *        external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ReDoSDataFlowConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Find re.compile calls
    exists(API::CallNode call |
      call = API::moduleImport("re").getMember("compile").getACall() and
      sink = call.getArg(0)
    )
  }
}

module ReDoSDataFlow = DataFlow::Global<ReDoSDataFlowConfig>;

from DataFlow::Node source, DataFlow::Node sink
where ReDoSDataFlow::flow(source, sink)
select sink, "Regex pattern receives untrusted input that could cause ReDoS"
